begin;
create table app.recommendations(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,reference_id uuid not null,baseline_result_id uuid not null,origin text not null default'TEACHER_AUTHORED'check(origin='TEACHER_AUTHORED'),observation text not null,interpretation text not null,recommendation text not null,rationale text not null,uncertainty text not null,activity_title text not null,instructions text not null,evidence_ids uuid[]not null,status text not null default'AWAITING_HUMAN'check(status in('AWAITING_HUMAN','APPROVED','REJECTED')),created_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,id,learner_id),foreign key(school_id,baseline_result_id,learner_id)references app.result_revisions(school_id,id,learner_id),foreign key(school_id,reference_id)references app.school_custom_references(school_id,id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id));
create table app.human_decisions(school_id uuid not null,id uuid not null default gen_random_uuid(),recommendation_id uuid not null,decision text not null check(decision in('APPROVE','REJECT')),reason text not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,recommendation_id),foreign key(school_id,recommendation_id)references app.recommendations(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.interventions(school_id uuid not null,id uuid not null default gen_random_uuid(),recommendation_id uuid not null,learner_id uuid not null,reference_id uuid not null,baseline_result_id uuid not null,title text not null,instructions text not null,status text not null default'ASSIGNED'check(status in('ASSIGNED','COMPLETED','MEASURED')),created_at timestamptz not null default clock_timestamp(),completed_at timestamptz,follow_up_assessment_id uuid,primary key(school_id,id),unique(school_id,id,learner_id),unique(school_id,recommendation_id),foreign key(school_id,recommendation_id,learner_id)references app.recommendations(school_id,id,learner_id),foreign key(school_id,baseline_result_id,learner_id)references app.result_revisions(school_id,id,learner_id),foreign key(school_id,reference_id)references app.school_custom_references(school_id,id),foreign key(school_id,follow_up_assessment_id)references app.assessments(school_id,id));
create table app.intervention_completions(school_id uuid not null,id uuid not null default gen_random_uuid(),intervention_id uuid not null,learner_id uuid not null,reflection text,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,intervention_id),foreign key(school_id,intervention_id,learner_id)references app.interventions(school_id,id,learner_id));
create table app.outcome_measurements(school_id uuid not null,id uuid not null default gen_random_uuid(),intervention_id uuid not null,learner_id uuid not null,baseline_result_id uuid not null,follow_up_result_id uuid not null,status text not null check(status in('improved','no_meaningful_change','inconclusive')),difference numeric not null,minimum_change numeric not null check(minimum_change>0),baseline_score numeric not null,baseline_max_score numeric not null,follow_up_score numeric not null,follow_up_max_score numeric not null,reason text not null,limitation text not null default'OBSERVED_CHANGE_NOT_CAUSAL_PROOF'check(limitation='OBSERVED_CHANGE_NOT_CAUSAL_PROOF'),measured_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,intervention_id),foreign key(school_id,intervention_id,learner_id)references app.interventions(school_id,id,learner_id),foreign key(school_id,baseline_result_id,learner_id)references app.result_revisions(school_id,id,learner_id),foreign key(school_id,follow_up_result_id,learner_id)references app.result_revisions(school_id,id,learner_id));
create function "authorization".improvement_access(target_school uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".academic_access(target_school)and"authorization".has_entitlement(target_school,'improvement'),false)$$;
create function "authorization".can_manage_baseline(target_school uuid,target_result uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".improvement_access(target_school)and exists(select 1 from app.result_revisions r where r.school_id=target_school and r.id=target_result and"authorization".can_mark_submission(target_school,r.submission_id)),false)$$;
create function "authorization".can_access_intervention(target_school uuid,target_intervention uuid,author_only boolean)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".improvement_access(target_school)and exists(select 1 from app.interventions i where i.school_id=target_school and i.id=target_intervention and("authorization".can_manage_baseline(target_school,i.baseline_result_id)or(author_only is false and"authorization".current_role(target_school)='student'and i.learner_id="authorization".actor_id()and"authorization".can_view_person(target_school,i.learner_id)))),false)$$;
create function internal.create_recommendation(baseline_id uuid,payload jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare r app.result_revisions;rid uuid;begin if not"authorization".can_manage_baseline("authorization".school_id(),baseline_id)then raise exception 'Baseline denied'using errcode='42501';end if;select*into r from app.result_revisions where school_id="authorization".school_id()and id=baseline_id;
insert into app.recommendations(school_id,learner_id,reference_id,baseline_result_id,observation,interpretation,recommendation,rationale,uncertainty,activity_title,instructions,evidence_ids,created_by)values(r.school_id,r.learner_id,r.reference_id,r.id,payload->>'observation',payload->>'interpretation',payload->>'recommendation',payload->>'rationale',payload->>'uncertainty',payload->>'activityTitle',payload->>'instructions',array[r.evidence_id],"authorization".actor_id())returning id into rid;return rid;end$$;
create function internal.decide_recommendation(target uuid,choice text,reason_text text,edited_title text,edited_instructions text)returns uuid language plpgsql security definer set search_path=''as $$declare r app.recommendations;d app.human_decisions;begin select*into r from app.recommendations where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_manage_baseline(r.school_id,r.baseline_result_id)then raise exception 'Recommendation denied'using errcode='42501';end if;if choice is null or choice not in('APPROVE','REJECT')or reason_text is null or length(reason_text)not between 1 and 4000 then raise exception 'Invalid decision'using errcode='22023';end if;
select*into d from app.human_decisions where school_id=r.school_id and recommendation_id=r.id;if found then if d.decision<>choice or d.reason<>reason_text then raise exception 'Decision immutable'using errcode='22023';end if;return r.id;end if;
insert into app.human_decisions(school_id,recommendation_id,decision,reason,actor_id)values(r.school_id,r.id,choice,reason_text,"authorization".actor_id());update app.recommendations set status=case when choice='APPROVE'then'APPROVED'else'REJECTED'end where school_id=r.school_id and id=r.id;
if choice='APPROVE'then insert into app.interventions(school_id,recommendation_id,learner_id,reference_id,baseline_result_id,title,instructions)values(r.school_id,r.id,r.learner_id,r.reference_id,r.baseline_result_id,coalesce(edited_title,r.activity_title),coalesce(edited_instructions,r.instructions));end if;return r.id;end$$;
create function internal.complete_intervention(target uuid,reflection_text text)returns uuid language plpgsql security definer set search_path=''as $$declare i app.interventions;begin select*into i from app.interventions where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_access_intervention(i.school_id,i.id,false)or"authorization".current_role(i.school_id)<>'student'or i.learner_id<>"authorization".actor_id()then raise exception 'Completion denied'using errcode='42501';end if;
insert into app.intervention_completions(school_id,intervention_id,learner_id,reflection)values(i.school_id,i.id,i.learner_id,reflection_text)on conflict(school_id,intervention_id)do nothing;update app.interventions set status='COMPLETED',completed_at=coalesce(completed_at,clock_timestamp())where school_id=i.school_id and id=i.id and status='ASSIGNED';return i.id;end$$;
create function internal.link_reassessment(target uuid,assessment_id uuid)returns uuid language plpgsql security definer set search_path=''as $$declare i app.interventions;b app.result_revisions;a app.assessments;ba app.assessments;begin select*into i from app.interventions where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_access_intervention(i.school_id,i.id,true)then raise exception 'Reassessment denied'using errcode='42501';end if;select*into b from app.result_revisions where school_id=i.school_id and id=i.baseline_result_id;select*into ba from app.assessments where school_id=b.school_id and id=b.assessment_id;select*into a from app.assessments where school_id=i.school_id and id=assessment_id;
if i.completed_at is null or a.id is null or a.id=b.assessment_id or a.course_id<>ba.course_id or a.academic_reference_id is distinct from b.reference_id or a.max_score<>b.max_score or a.model<>'numeric'or(i.follow_up_assessment_id is not null and i.follow_up_assessment_id<>assessment_id)then raise exception 'Incompatible follow-up assessment'using errcode='22023';end if;update app.interventions set follow_up_assessment_id=assessment_id where school_id=i.school_id and id=i.id;return i.id;end$$;
create function internal.measure_intervention(target uuid,followup_id uuid,minimum_change numeric)returns uuid language plpgsql security definer set search_path=''as $$declare i app.interventions;b app.result_revisions;f app.result_revisions;existing app.outcome_measurements;oid uuid;delta numeric;state text;reason_text text;begin select*into i from app.interventions where school_id="authorization".school_id()and id=target for update;if not found or not"authorization".can_access_intervention(i.school_id,i.id,true)then raise exception 'Measurement denied'using errcode='42501';end if;
select*into b from app.result_revisions where school_id=i.school_id and id=i.baseline_result_id;select*into f from app.result_revisions where school_id=i.school_id and id=followup_id;
if minimum_change is null or minimum_change<=0 or minimum_change>100000 or f.id is null or i.completed_at is null or f.assessment_id is distinct from i.follow_up_assessment_id or f.learner_id<>i.learner_id or f.reference_id<>b.reference_id or f.reference_version<>b.reference_version or f.max_score<>b.max_score or f.created_at<=i.completed_at then raise exception 'Incompatible measured evidence'using errcode='22023';end if;
select*into existing from app.outcome_measurements where school_id=i.school_id and intervention_id=i.id;if found then if existing.follow_up_result_id<>followup_id or existing.minimum_change<>minimum_change then raise exception 'Measurement immutable'using errcode='22023';end if;return existing.id;end if;
delta:=f.score-b.score;state:=case when delta>=minimum_change then'improved'when abs(delta)<minimum_change then'no_meaningful_change'else'inconclusive'end;reason_text:=case when delta<=-minimum_change then'FOLLOW_UP_LOWER'else'OBSERVED_RAW_SCORE_CHANGE'end;
insert into app.outcome_measurements(school_id,intervention_id,learner_id,baseline_result_id,follow_up_result_id,status,difference,minimum_change,baseline_score,baseline_max_score,follow_up_score,follow_up_max_score,reason)values(i.school_id,i.id,i.learner_id,b.id,f.id,state,delta,minimum_change,b.score,b.max_score,f.score,f.max_score,reason_text)returning id into oid;update app.interventions set status='MEASURED'where school_id=i.school_id and id=i.id;return oid;end$$;
do $$declare tab text;begin foreach tab in array array['recommendations','human_decisions','interventions','intervention_completions','outcome_measurements']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);end loop;foreach tab in array array['human_decisions','intervention_completions','outcome_measurements']loop execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);end loop;end$$;
create policy recommendations_read on app.recommendations for select to cuevo_api using("authorization".can_manage_baseline(school_id,baseline_result_id)or("authorization".improvement_access(school_id)and"authorization".current_role(school_id)='coordinator'));
create policy intervention_read on app.interventions for select to cuevo_api using("authorization".can_access_intervention(school_id,id,false)or("authorization".improvement_access(school_id)and"authorization".current_role(school_id)='coordinator'));
create policy outcome_read on app.outcome_measurements for select to cuevo_api using("authorization".can_access_intervention(school_id,intervention_id,false)or("authorization".improvement_access(school_id)and"authorization".current_role(school_id)='coordinator'));
revoke all on app.recommendations,app.human_decisions,app.interventions,app.intervention_completions,app.outcome_measurements from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;grant select on app.recommendations,app.interventions,app.outcome_measurements to cuevo_api;
revoke execute on function "authorization".improvement_access(uuid),"authorization".can_manage_baseline(uuid,uuid),"authorization".can_access_intervention(uuid,uuid,boolean)from public,anon,authenticated,service_role,cuevo_worker;grant execute on function "authorization".improvement_access(uuid),"authorization".can_manage_baseline(uuid,uuid),"authorization".can_access_intervention(uuid,uuid,boolean)to cuevo_api;
revoke execute on function internal.create_recommendation(uuid,jsonb),internal.decide_recommendation(uuid,text,text,text,text),internal.complete_intervention(uuid,text),internal.link_reassessment(uuid,uuid),internal.measure_intervention(uuid,uuid,numeric)from public,anon,authenticated,service_role,cuevo_worker;grant execute on function internal.create_recommendation(uuid,jsonb),internal.decide_recommendation(uuid,text,text,text,text),internal.complete_intervention(uuid,text),internal.link_reassessment(uuid,uuid),internal.measure_intervention(uuid,uuid,numeric)to cuevo_api;
commit;
